package com.wissenup.domain.timetable.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="class_timetables") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class ClassTimetable { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="class_timetable_id") private Long classTimetableId; @Column(name="organization_id") private Long organizationId; @Column(name="academic_year_id") private Long academicYearId; @Column(name="class_id") private Long classId; @Column(name="section_id") private Long sectionId; private String status; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="created_by") private Long createdBy; @Column(name="updated_at") private LocalDateTime updatedAt; @Column(name="updated_by") private Long updatedBy; @PrePersist void create(){if(status==null)status="ACTIVE";if(createdAt==null)createdAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }
